package main

import (
	"fmt"
	"os"
	"path/filepath"
	"strings"
)

// spliceTransferCollision is the incorrect type go-daml emits when a utility package
// defines a local Transfer2 (Utility.Registry.Transfer) and also references
// Splice.Api.Token.Transfer via a qualified import.
const spliceTransferCollision = "splice_api_token_transfer_instruction_v1.Transfer2"

const spliceTransferCorrect = "splice_api_token_transfer_instruction_v1.Transfer"

const tuple2ShimBody = `

// Code generated by contracts/cmd/bindings. DO NOT EDIT.

// Tuple2 mirrors GHC.Tuple from daml-prim (referenced by utility DARs, not emitted by codegen).
type Tuple2 struct {
	First  any ` + "`json:\"_1\"`" + `
	Second any ` + "`json:\"_2\"`" + `
}
`

var tuple2ShimPackages = []struct {
	dir       string
	packageAs string
}{
	{dir: filepath.Join("utility", "credential_v0"), packageAs: "credential_v0"},
	{dir: filepath.Join("utility", "registry_holding_v0"), packageAs: "registry_holding_v0"},
}

func writeTuple2Shims(artifactsDir string) error {
	for _, pkg := range tuple2ShimPackages {
		content := "package " + pkg.packageAs + tuple2ShimBody

		outputFile := filepath.Join(artifactsDir, pkg.dir, "tuple2.go")
		if err := os.MkdirAll(filepath.Dir(outputFile), 0o755); err != nil {
			return fmt.Errorf("create tuple2 shim dir %q: %w", filepath.Dir(outputFile), err)
		}
		if err := os.WriteFile(outputFile, []byte(content), 0o644); err != nil {
			return fmt.Errorf("write tuple2 shim %q: %w", outputFile, err)
		}
	}

	return nil
}

func patchUtilityBindingCollisions(artifactsDir string) error {
	utilityDir := filepath.Join(artifactsDir, "utility")
	entries, err := os.ReadDir(utilityDir)
	if err != nil {
		if os.IsNotExist(err) {
			return nil
		}
		return fmt.Errorf("read utility bindings dir %q: %w", utilityDir, err)
	}

	for _, entry := range entries {
		if !entry.IsDir() {
			continue
		}

		goFile := filepath.Join(utilityDir, entry.Name(), entry.Name()+".go")
		data, err := os.ReadFile(goFile)
		if err != nil {
			if os.IsNotExist(err) {
				continue
			}
			return fmt.Errorf("read utility bindings %q: %w", goFile, err)
		}

		patched := patchSpliceTransferCollision(data)
		if string(patched) == string(data) {
			continue
		}

		if err := os.WriteFile(goFile, patched, 0o644); err != nil {
			return fmt.Errorf("write patched utility bindings %q: %w", goFile, err)
		}
	}

	return nil
}

func patchSpliceTransferCollision(data []byte) []byte {
	return []byte(strings.ReplaceAll(string(data), spliceTransferCollision, spliceTransferCorrect))
}
